+package queue
+
+import (
+	"testing"
+	"time"
+)
+
+func TestJitteredGrows(t *testing.T) {
+	b := Jittered(time.Second)
+	prev := time.Duration(0)
+	for n := 0; n < 5; n++ {
+		d := b(n)
+		if d < prev {
+			t.Fatalf("attempt %d: %v is shorter than %v", n, d, prev)
+		}
+		prev = d
+	}
+}
+
+func TestJitteredBounds(t *testing.T) {
+	if d := Jittered(time.Second)(0); d < time.Second || d > 1250*time.Millisecond {
+		t.Fatalf("got %v, want 1s..1.25s", d)
+	}
+}

