+package queue
+
+// Dedupe drops a job when one with the same key is already pending.
+type Dedupe struct {
+	seen map[string]struct{}
+}
+
+func (d *Dedupe) Admit(key string) bool {
+	if d.seen == nil {
+		d.seen = map[string]struct{}{}
+	}
+	if _, ok := d.seen[key]; ok {
+		return false
+	}
+	d.seen[key] = struct{}{}
+	return true
+}

